window.DataTrailPythonExercises = [{"title":"01 · Your first Python output","unit":"Getting started","prompt":"Use print() to display exactly: Hello, DataTrail! The message must appear as one line.","setup":"","starter":"print(\"Replace this with the required message\")","hint":"print() displays the value inside its parentheses. Text needs matching quotation marks.","solution":"print(\"Hello, DataTrail!\")","tests":[{"name":"Displays the exact message","code":"assert __output__.strip() == \"Hello, DataTrail!\""},{"name":"Displays one line","code":"assert len(__output__.strip().splitlines()) == 1"}]},{"title":"02 · Print messages and add comments","unit":"Getting started","prompt":"Add a comment that explains the next line, then use print() to display exactly: Python is running. The comment should begin with #.","setup":"","starter":"# Write a short comment explaining this line\nprint(\"Replace this message\")","hint":"Comments begin with #. They explain code to a reader but are not executed. Put the exact display text inside print().","solution":"# Display a short confirmation\nprint(\"Python is running\")","tests":[{"name":"Displays the exact message","code":"assert __output__.strip() == \"Python is running\""},{"name":"Includes a real Python comment","code":"assert any(line.lstrip().startswith(\"#\") for line in __source__.splitlines())"}]},{"title":"03 · Evaluate arithmetic expressions","unit":"Getting started","prompt":"Calculate the total for 3 items costing ₹250 each, then add 18% tax. Store the pre-tax subtotal in subtotal and the final value in total_with_tax.","setup":"","starter":"unit_price = 250\nquantity = 3\ntax_rate = 0.18\nsubtotal = \ntotal_with_tax = ","hint":"Multiply unit_price by quantity first. Apply tax to the subtotal, then add the tax. Use parentheses to make the calculation clear.","solution":"unit_price = 250\nquantity = 3\ntax_rate = 0.18\nsubtotal = unit_price * quantity\ntotal_with_tax = subtotal * (1 + tax_rate)","tests":[{"name":"Calculates the subtotal","code":"assert subtotal == 750"},{"name":"Calculates the tax-inclusive total","code":"assert total_with_tax == 885"},{"name":"Keeps the total numeric","code":"assert isinstance(total_with_tax, (int, float))"}]},{"title":"04 · Create and reuse variables","unit":"Getting started","prompt":"Create three variables: customer_name, order_count and revenue using the supplied values. Return a dictionary named invoice_summary containing those three fields.","setup":"","starter":"customer_name = \"Asha\"\norder_count = 3\nrevenue = 3750\ninvoice_summary = ","hint":"Use a dictionary with the keys customer_name, order_count and revenue. The values should be the variables, not text in quotation marks.","solution":"customer_name = \"Asha\"\norder_count = 3\nrevenue = 3750\ninvoice_summary = {\n    \"customer_name\": customer_name,\n    \"order_count\": order_count,\n    \"revenue\": revenue\n}","tests":[{"name":"Stores the customer name","code":"assert invoice_summary[\"customer_name\"] == \"Asha\""},{"name":"Stores the order count","code":"assert invoice_summary[\"order_count\"] == 3"},{"name":"Stores the revenue value","code":"assert invoice_summary[\"revenue\"] == 3750"}]},{"title":"05 · Recognise Python data types","unit":"Getting started","prompt":"Write describe_types(values). It should return a list with the Python type name of every value, in the same order.","setup":"","starter":"def describe_types(values):\n    # Return each value's type name\n    pass","hint":"Use a list comprehension with type(value).__name__. Keep the same order as the input list.","solution":"def describe_types(values):\n    return [type(value).__name__ for value in values]","tests":[{"name":"Recognises the four common data types","code":"assert describe_types([10, 2.5, \"Asha\", True]) == [\"int\", \"float\", \"str\", \"bool\"]"},{"name":"Handles an empty list","code":"assert describe_types([]) == []"},{"name":"Keeps the order of values","code":"assert describe_types([\"x\", 5]) == [\"str\", \"int\"]"}]},{"title":"06 · Calculate a business profit","unit":"Getting started","prompt":"The setup gives you revenue and expenses. Create a variable profit equal to revenue minus expenses, then print it.","setup":"revenue = 18000\nexpenses = 11200","starter":"revenue = 18000\nexpenses = 11200\nprofit = \nprint(profit)","hint":"Assign revenue - expenses to profit. Do not put the variable name in quotation marks.","solution":"revenue = 18000\nexpenses = 11200\nprofit = revenue - expenses\nprint(profit)","tests":[{"name":"Calculates the correct profit","code":"assert profit == 6800"},{"name":"Keeps profit numeric","code":"assert isinstance(profit, (int, float))"}]},{"title":"07 · Build a readable invoice message","unit":"Getting started","prompt":"Create invoice_message using an f-string. It must read: Invoice INV-204 for Asha: ₹1,250. The variables are supplied.","setup":"invoice_id = \"INV-204\"\ncustomer = \"Asha\"\namount = 1250","starter":"invoice_id = \"INV-204\"\ncustomer = \"Asha\"\namount = 1250\ninvoice_message = ","hint":"Start the string with f before the quote. Insert each variable inside curly braces. Use :, to format a number with grouping commas.","solution":"invoice_id = \"INV-204\"\ncustomer = \"Asha\"\namount = 1250\ninvoice_message = f\"Invoice {invoice_id} for {customer}: ₹{amount:,}\"","tests":[{"name":"Includes the invoice ID","code":"assert \"INV-204\" in invoice_message"},{"name":"Includes the customer","code":"assert \"Asha\" in invoice_message"},{"name":"Formats the amount","code":"assert invoice_message == \"Invoice INV-204 for Asha: ₹1,250\""}]},{"title":"08 · Convert text into a number","unit":"Getting started","prompt":"The source amount arrives as text '1200'. Convert it to an integer named amount, calculate 18% tax, and store the total including tax in gross_amount.","setup":"amount_text = \"1200\"","starter":"amount_text = \"1200\"\namount = \ntax = \ngross_amount = ","hint":"Use int() for the source text. Calculate tax as amount * 0.18, then add it to amount.","solution":"amount_text = \"1200\"\namount = int(amount_text)\ntax = amount * 0.18\ngross_amount = amount + tax","tests":[{"name":"Converts the input to an integer","code":"assert amount == 1200 and isinstance(amount, int)"},{"name":"Calculates tax","code":"assert tax == 216"},{"name":"Calculates the gross amount","code":"assert gross_amount == 1416"}]},{"title":"09 · Create a Boolean business rule","unit":"Logic and repetition","prompt":"Write is_high_value(amount). Return True when amount is at least 5,000, and False otherwise.","setup":"","starter":"def is_high_value(amount):\n    # Return a Boolean based on the 5,000 threshold\n    pass","hint":"Use a comparison expression with >= 5000. The expression already returns True or False.","solution":"def is_high_value(amount):\n    return amount >= 5000","tests":[{"name":"Includes the exact threshold","code":"assert is_high_value(5000) is True"},{"name":"Accepts a value above the threshold","code":"assert is_high_value(6200) is True"},{"name":"Rejects a value below the threshold","code":"assert is_high_value(4999) is False"}]},{"title":"10 · Combine conditions with and","unit":"Logic and repetition","prompt":"Write is_discount_eligible(is_member, order_amount). Return True only when the customer is a member AND the order is at least ₹2,000.","setup":"","starter":"def is_discount_eligible(is_member, order_amount):\n    # Combine both business conditions\n    pass","hint":"Use the and operator between the membership check and the amount comparison.","solution":"def is_discount_eligible(is_member, order_amount):\n    return is_member and order_amount >= 2000","tests":[{"name":"Approves a qualifying member order","code":"assert is_discount_eligible(True, 2500) is True"},{"name":"Rejects a non-member","code":"assert is_discount_eligible(False, 2500) is False"},{"name":"Rejects an order below the threshold","code":"assert is_discount_eligible(True, 1999) is False"},{"name":"Includes the exact threshold","code":"assert is_discount_eligible(True, 2000) is True"}]},{"title":"11 · Classify an order with if and elif","unit":"Logic and repetition","prompt":"Write classify_order(amount). Return Large for 5,000 or more, Medium for 2,000 to 4,999, and Small for less than 2,000.","setup":"","starter":"def classify_order(amount):\n    # Add the three categories\n    pass","hint":"Check the largest threshold first. Return a string from each branch.","solution":"def classify_order(amount):\n    if amount >= 5000:\n        return \"Large\"\n    elif amount >= 2000:\n        return \"Medium\"\n    else:\n        return \"Small\"","tests":[{"name":"Classifies a large order","code":"assert classify_order(6200) == \"Large\""},{"name":"Classifies the boundary as Large","code":"assert classify_order(5000) == \"Large\""},{"name":"Classifies a medium order","code":"assert classify_order(3500) == \"Medium\""},{"name":"Classifies a small order","code":"assert classify_order(900) == \"Small\""}]},{"title":"12 · Total a list using a loop","unit":"Logic and repetition","prompt":"Write total_amounts(amounts). Use a for loop to return the sum of values. Do not use sum() for this exercise.","setup":"","starter":"def total_amounts(amounts):\n    total = 0\n    # Loop through the amounts and update total\n    return total","hint":"For every amount in amounts, add it to total. Return total after the loop has finished.","solution":"def total_amounts(amounts):\n    total = 0\n    for amount in amounts:\n        total += amount\n    return total","tests":[{"name":"Totals three values","code":"assert total_amounts([100, 250, 80]) == 430"},{"name":"Handles one value","code":"assert total_amounts([75]) == 75"},{"name":"Handles an empty list","code":"assert total_amounts([]) == 0"}]},{"title":"13 · Number records with enumerate","unit":"Logic and repetition","prompt":"Create numbered_customers as a list of (position, name) pairs. Positions must begin at 1, not zero.","setup":"names = [\"Asha\", \"Rahul\", \"Meera\"]","starter":"names = [\"Asha\", \"Rahul\", \"Meera\"]\nnumbered_customers = ","hint":"Use enumerate(names, start=1), then convert its result to a list.","solution":"names = [\"Asha\", \"Rahul\", \"Meera\"]\nnumbered_customers = list(enumerate(names, start=1))","tests":[{"name":"Starts numbering at one","code":"assert numbered_customers[0] == (1, \"Asha\")"},{"name":"Keeps the name-position pairs","code":"assert numbered_customers == [(1, \"Asha\"), (2, \"Rahul\"), (3, \"Meera\")]"}]},{"title":"14 · Repeat work with a while loop","unit":"Logic and repetition","prompt":"Write countdown(start). Use a while loop to return a list counting down from start to 1. If start is zero or negative, return an empty list.","setup":"","starter":"def countdown(start):\n    result = []\n    # Use a while loop\n    return result","hint":"While the remaining number is greater than zero, append it to result and subtract one.","solution":"def countdown(start):\n    result = []\n    remaining = start\n    while remaining > 0:\n        result.append(remaining)\n        remaining -= 1\n    return result","tests":[{"name":"Counts down from five","code":"assert countdown(5) == [5, 4, 3, 2, 1]"},{"name":"Handles one","code":"assert countdown(1) == [1]"},{"name":"Handles zero","code":"assert countdown(0) == []"},{"name":"Handles a negative start","code":"assert countdown(-2) == []"}]},{"title":"15 · Filter high-value orders","unit":"Python collections","prompt":"Use a for loop to create high_value_orders containing only amounts greater than or equal to 5,000. Keep the original order.","setup":"amounts = [1200, 6500, 800, 7200, 5000]","starter":"amounts = [1200, 6500, 800, 7200, 5000]\nhigh_value_orders = []\n# Add only qualifying amounts","hint":"Loop through amounts. Inside the loop, use an if condition and append qualifying values.","solution":"amounts = [1200, 6500, 800, 7200, 5000]\nhigh_value_orders = []\nfor amount in amounts:\n    if amount >= 5000:\n        high_value_orders.append(amount)","tests":[{"name":"Keeps qualifying amounts","code":"assert high_value_orders == [6500, 7200, 5000]"},{"name":"Does not include below-threshold values","code":"assert all(amount >= 5000 for amount in high_value_orders)"}]},{"title":"16 · Slice a list and append a value","unit":"Python collections","prompt":"Write extend_and_preview(amounts, new_amount). Return a tuple: the first two original amounts, and a new list that includes new_amount at the end. Do not modify the original list.","setup":"","starter":"def extend_and_preview(amounts, new_amount):\n    # Use a slice and append on a copy\n    pass","hint":"Use amounts[:2] for the preview. Make a copy with amounts.copy(), append new_amount to the copy, and return both values as a tuple.","solution":"def extend_and_preview(amounts, new_amount):\n    first_two = amounts[:2]\n    updated = amounts.copy()\n    updated.append(new_amount)\n    return first_two, updated","tests":[{"name":"Returns the first two values","code":"assert extend_and_preview([100, 200, 300], 400)[0] == [100, 200]"},{"name":"Appends to the copied list","code":"assert extend_and_preview([100, 200, 300], 400)[1] == [100, 200, 300, 400]"},{"name":"Does not change the original list","code":"values = [100, 200]\nextend_and_preview(values, 300)\nassert values == [100, 200]"},{"name":"Handles a short list","code":"assert extend_and_preview([50], 60) == ([50], [50, 60])"}]},{"title":"17 · Unpack a tuple into named values","unit":"Python collections","prompt":"Write unpack_customer(record). The record is a tuple containing customer name, city and revenue. Return a dictionary with those three fields.","setup":"","starter":"def unpack_customer(record):\n    # Unpack the tuple and build a dictionary\n    pass","hint":"Unpack the three tuple values into named variables. Then return a dictionary that uses those values.","solution":"def unpack_customer(record):\n    customer_name, city, revenue = record\n    return {\n        \"customer_name\": customer_name,\n        \"city\": city,\n        \"revenue\": revenue\n    }","tests":[{"name":"Unpacks all three values","code":"assert unpack_customer((\"Asha\", \"Chennai\", 1200)) == {\"customer_name\": \"Asha\", \"city\": \"Chennai\", \"revenue\": 1200}"},{"name":"Preserves a numeric revenue value","code":"assert isinstance(unpack_customer((\"Rahul\", \"Pune\", 900))[\"revenue\"], int)"},{"name":"Handles a decimal revenue value","code":"assert unpack_customer((\"Meera\", \"Kochi\", 99.5))[\"revenue\"] == 99.5"}]},{"title":"18 · Aggregate revenue by city","unit":"Python collections","prompt":"Build sales_by_city from the supplied rows. Add together sales that belong to the same city.","setup":"rows = [(\"Chennai\", 1200), (\"Pune\", 900), (\"Chennai\", 1500), (\"Pune\", 300)]","starter":"rows = [(\"Chennai\", 1200), (\"Pune\", 900), (\"Chennai\", 1500), (\"Pune\", 300)]\nsales_by_city = {}\n# Loop through each city and amount","hint":"Unpack each tuple into city and amount. Use sales_by_city.get(city, 0) to start a new city at zero.","solution":"rows = [(\"Chennai\", 1200), (\"Pune\", 900), (\"Chennai\", 1500), (\"Pune\", 300)]\nsales_by_city = {}\nfor city, amount in rows:\n    sales_by_city[city] = sales_by_city.get(city, 0) + amount","tests":[{"name":"Combines repeated Chennai rows","code":"assert sales_by_city[\"Chennai\"] == 2700"},{"name":"Combines repeated Pune rows","code":"assert sales_by_city[\"Pune\"] == 1200"},{"name":"Accounts for all revenue","code":"assert sum(sales_by_city.values()) == 3900"}]},{"title":"19 · Find unique cities with a set","unit":"Python collections","prompt":"Create unique_cities from the supplied list and calculate the number of unique cities.","setup":"cities = [\"Chennai\", \"Pune\", \"Chennai\", \"Kochi\", \"Pune\"]","starter":"cities = [\"Chennai\", \"Pune\", \"Chennai\", \"Kochi\", \"Pune\"]\nunique_cities = \nunique_city_count = ","hint":"Convert the list to a set to remove duplicates. Use len() to count the unique values.","solution":"cities = [\"Chennai\", \"Pune\", \"Chennai\", \"Kochi\", \"Pune\"]\nunique_cities = set(cities)\nunique_city_count = len(unique_cities)","tests":[{"name":"Counts three unique cities","code":"assert unique_city_count == 3"},{"name":"Contains the expected city names","code":"assert unique_cities == {\"Chennai\", \"Pune\", \"Kochi\"}"}]},{"title":"20 · Clean customer names","unit":"Python collections","prompt":"Write clean_name(name). Remove spaces from both ends and return the name in title case.","setup":"","starter":"def clean_name(name):\n    # Clean the supplied name\n    pass","hint":"Strings have strip() and title() methods. Chain them on the name and return the result.","solution":"def clean_name(name):\n    return name.strip().title()","tests":[{"name":"Removes leading spaces","code":"assert clean_name(\"  asha\") == \"Asha\""},{"name":"Normalises capital letters","code":"assert clean_name(\"RAHUL \") == \"Rahul\""},{"name":"Handles several words","code":"assert clean_name(\"  meera sharma  \") == \"Meera Sharma\""}]},{"title":"21 · Write a reusable profit function","unit":"Reusable programs","prompt":"Write calculate_profit(revenue, expenses). It must return revenue minus expenses. Do not print the result inside the function.","setup":"","starter":"def calculate_profit(revenue, expenses):\n    # Return revenue minus expenses\n    pass","hint":"Use a return statement. The function should work for new values each time it is called.","solution":"def calculate_profit(revenue, expenses):\n    return revenue - expenses","tests":[{"name":"Calculates profit for the first business case","code":"assert calculate_profit(15000, 8400) == 6600"},{"name":"Calculates profit for another case","code":"assert calculate_profit(2000, 500) == 1500"},{"name":"Returns a numeric value","code":"assert isinstance(calculate_profit(10, 3), (int, float))"}]},{"title":"22 · Final project: build a sales summary","unit":"Analyst practice","prompt":"Implement summarise_sales(csv_text). Return a dictionary with total_orders, paid_revenue and revenue_by_city. Count every order, but include only Paid rows in revenue totals. Standardise city labels.","setup":"","starter":"def summarise_sales(csv_text):\n    import csv\n    from io import StringIO\n    # Set up totals, read each row and build the summary\n    pass","hint":"Use DictReader. Count each row. For Paid rows, convert amount to float, add it to paid_revenue, clean city with strip().title(), and update revenue_by_city with .get(city, 0).","solution":"def summarise_sales(csv_text):\n    import csv\n    from io import StringIO\n    total_orders = 0\n    paid_revenue = 0.0\n    revenue_by_city = {}\n    for row in csv.DictReader(StringIO(csv_text)):\n        total_orders += 1\n        if row[\"status\"] == \"Paid\":\n            amount = float(row[\"amount\"])\n            paid_revenue += amount\n            city = row[\"city\"].strip().title()\n            revenue_by_city[city] = revenue_by_city.get(city, 0) + amount\n    return {\"total_orders\": total_orders, \"paid_revenue\": paid_revenue, \"revenue_by_city\": revenue_by_city}","tests":[{"name":"Counts every order row","code":"sample=\"city,amount,status\\nchennai,1200,Paid\\nPune,900,Pending\\nCHENNAI,1500,Paid\"\nresult=summarise_sales(sample)\nassert result[\"total_orders\"] == 3"},{"name":"Totals paid revenue only","code":"sample=\"city,amount,status\\nchennai,1200,Paid\\nPune,900,Pending\\nCHENNAI,1500,Paid\"\nresult=summarise_sales(sample)\nassert result[\"paid_revenue\"] == 2700"},{"name":"Cleans and groups city labels","code":"sample=\"city,amount,status\\nchennai,1200,Paid\\nPune,900,Pending\\nCHENNAI,1500,Paid\"\nresult=summarise_sales(sample)\nassert result[\"revenue_by_city\"] == {\"Chennai\": 2700}"},{"name":"Handles no paid orders","code":"sample=\"city,amount,status\\nPune,900,Pending\"\nresult=summarise_sales(sample)\nassert result[\"paid_revenue\"] == 0 and result[\"revenue_by_city\"] == {}"}]},{"title":"23 · Write a reusable discount function","unit":"Reusable programs","prompt":"Write discounted_price(price, rate=0.10). Return the price after discount. The caller may use the default rate or supply another rate.","setup":"","starter":"def discounted_price(price, rate=0.10):\n    # Return price after discount\n    pass","hint":"The discounted price equals price multiplied by (1 - rate). Keep 0.10 as the default parameter.","solution":"def discounted_price(price, rate=0.10):\n    return price * (1 - rate)","tests":[{"name":"Uses the default discount","code":"assert discounted_price(1000) == 900"},{"name":"Accepts a supplied discount rate","code":"assert discounted_price(1000, rate=0.20) == 800"},{"name":"Handles zero discount","code":"assert discounted_price(500, rate=0) == 500"}]},{"title":"24 · Understand local function scope","unit":"Reusable programs","prompt":"Write average_amounts(values). Create a local variable total, calculate the average and return it. For an empty list, return None. Do not create a global variable named total.","setup":"","starter":"def average_amounts(values):\n    # Create a local total and return the average\n    pass","hint":"Calculate total inside the function. If the list is empty, return None before dividing. Then divide by len(values).","solution":"def average_amounts(values):\n    if not values:\n        return None\n    total = sum(values)\n    average = total / len(values)\n    return average","tests":[{"name":"Calculates an average","code":"assert average_amounts([100, 200, 300]) == 200"},{"name":"Handles two values","code":"assert average_amounts([1200, 900]) == 1050"},{"name":"Handles an empty list","code":"assert average_amounts([]) is None"},{"name":"Does not create a global total","code":"assert \"total\" not in globals()"}]},{"title":"25 · Import a standard-library module","unit":"Reusable programs","prompt":"Write mean_score(scores). Use the statistics module to calculate and return the arithmetic mean. Do not print it.","setup":"","starter":"def mean_score(scores):\n    # Import the module and return the mean\n    pass","hint":"Import statistics inside the function or above it. Then call statistics.mean(scores).","solution":"def mean_score(scores):\n    import statistics\n    return statistics.mean(scores)","tests":[{"name":"Calculates the mean of three scores","code":"assert mean_score([70, 80, 90]) == 80"},{"name":"Works with two values","code":"assert mean_score([10, 20]) == 15"},{"name":"Returns a numeric value","code":"assert isinstance(mean_score([1, 2, 3]), (int, float))"}]},{"title":"26 · Debug a type error from a traceback","unit":"Reusable programs","prompt":"The starter has a common TypeError bug: it tries to add text and a number. Fix it by converting amount_text to an integer before adding fee. Write add_fee(amount_text, fee).","setup":"","starter":"def add_fee(amount_text, fee):\n    # Convert the amount before adding the fee\n    return amount_text + fee","hint":"Convert amount_text with int() before using +. Keep the returned value numeric.","solution":"def add_fee(amount_text, fee):\n    amount = int(amount_text)\n    return amount + fee","tests":[{"name":"Fixes the TypeError for numeric text","code":"assert add_fee(\"500\", 50) == 550"},{"name":"Works with a larger amount","code":"assert add_fee(\"1200\", 100) == 1300"},{"name":"Returns a numeric result","code":"assert isinstance(add_fee(\"10\", 1), int)"}]},{"title":"27 · Convert messy numeric input safely","unit":"Reusable programs","prompt":"Write safe_float(value). Return a float when conversion is possible. If the value is invalid, return None rather than crashing.","setup":"","starter":"def safe_float(value):\n    # Try to convert value; handle invalid numeric text\n    pass","hint":"Put float(value) inside try. Catch ValueError and return None in the except block.","solution":"def safe_float(value):\n    try:\n        return float(value)\n    except ValueError:\n        return None","tests":[{"name":"Converts a numeric string","code":"assert safe_float(\"12.5\") == 12.5"},{"name":"Converts a whole-number string","code":"assert safe_float(\"40\") == 40.0"},{"name":"Returns None for invalid text","code":"assert safe_float(\"not a number\") is None"}]},{"title":"28 · Read and write a text file","unit":"Files and data","prompt":"Write save_and_read_text(filename, text). Save the text to the given file using UTF-8, then read the text back and return it.","setup":"","starter":"def save_and_read_text(filename, text):\n    from pathlib import Path\n    # Write the text, then read it back\n    pass","hint":"Create a Path from filename. Call write_text(text, encoding='utf-8'), then return read_text(encoding='utf-8').","solution":"def save_and_read_text(filename, text):\n    from pathlib import Path\n    path = Path(filename)\n    path.write_text(text, encoding=\"utf-8\")\n    return path.read_text(encoding=\"utf-8\")","tests":[{"name":"Writes and reads ordinary text","code":"assert save_and_read_text(\"datatrail_note.txt\", \"Python practice\") == \"Python practice\""},{"name":"Preserves Unicode text","code":"assert save_and_read_text(\"datatrail_unicode.txt\", \"Asha · ₹1,250\") == \"Asha · ₹1,250\""},{"name":"Handles an empty file","code":"assert save_and_read_text(\"datatrail_empty.txt\", \"\") == \"\""},{"name":"Cleans up exercise files","code":"from pathlib import Path\nfor name in [\"datatrail_note.txt\", \"datatrail_unicode.txt\", \"datatrail_empty.txt\"]:\n    Path(name).unlink(missing_ok=True)"}]},{"title":"29 · Read CSV rows and total paid revenue","unit":"Files and data","prompt":"Implement paid_revenue_from_csv(csv_text). Use DictReader and return the total amount for rows whose status is Paid.","setup":"","starter":"def paid_revenue_from_csv(csv_text):\n    import csv\n    from io import StringIO\n    # Read rows and total Paid amounts\n    pass","hint":"Create a DictReader from StringIO(csv_text). Loop over rows, check status, convert amount to float and add it to a total.","solution":"def paid_revenue_from_csv(csv_text):\n    import csv\n    from io import StringIO\n    total = 0.0\n    for row in csv.DictReader(StringIO(csv_text)):\n        if row[\"status\"] == \"Paid\":\n            total += float(row[\"amount\"])\n    return total","tests":[{"name":"Totals only Paid records","code":"sample = \"order_id,amount,status\\n1,1200,Paid\\n2,900,Pending\\n3,1500,Paid\"\nassert paid_revenue_from_csv(sample) == 2700"},{"name":"Returns zero when nothing is paid","code":"sample = \"order_id,amount,status\\n1,900,Pending\"\nassert paid_revenue_from_csv(sample) == 0"},{"name":"Handles a CSV with headers only","code":"sample = \"order_id,amount,status\\n\"\nassert paid_revenue_from_csv(sample) == 0"}]},{"title":"30 · Read a JSON order","unit":"Files and data","prompt":"Implement get_order_total(payload). The JSON text contains order_id and a nested details object with amount. Return the amount as a number.","setup":"","starter":"def get_order_total(payload):\n    import json\n    # Parse the JSON and return details.amount\n    pass","hint":"Use json.loads(payload) to create a dictionary, then access ['details']['amount'].","solution":"def get_order_total(payload):\n    import json\n    order = json.loads(payload)\n    return float(order[\"details\"][\"amount\"])","tests":[{"name":"Reads a nested amount","code":"payload = '{\"order_id\": 10, \"details\": {\"amount\": 1200}}'\nassert get_order_total(payload) == 1200"},{"name":"Handles a decimal amount","code":"payload = '{\"order_id\": 11, \"details\": {\"amount\": 49.95}}'\nassert get_order_total(payload) == 49.95"}]},{"title":"31 · Convert a date into a reporting month","unit":"Files and data","prompt":"Implement month_label(date_text). The input format is YYYY-MM-DD. Return text in YYYY-MM format.","setup":"","starter":"def month_label(date_text):\n    from datetime import datetime\n    # Parse the date and format its year and month\n    pass","hint":"Use datetime.strptime(date_text, '%Y-%m-%d'), then strftime('%Y-%m') on the result.","solution":"def month_label(date_text):\n    from datetime import datetime\n    date_value = datetime.strptime(date_text, \"%Y-%m-%d\")\n    return date_value.strftime(\"%Y-%m\")","tests":[{"name":"Formats October correctly","code":"assert month_label(\"2026-10-19\") == \"2026-10\""},{"name":"Formats a different month","code":"assert month_label(\"2025-02-01\") == \"2025-02\""}]},{"title":"32 · Use a comprehension to clean values","unit":"Analyst practice","prompt":"Create positive_values using a list comprehension. Keep only values greater than zero and preserve their order.","setup":"","starter":"values = [-2, 5, 0, 8, -1]\npositive_values = ","hint":"A list comprehension goes inside square brackets: expression, for value in values, then if value > 0.","solution":"values = [-2, 5, 0, 8, -1]\npositive_values = [value for value in values if value > 0]","tests":[{"name":"Keeps positive numbers only","code":"assert positive_values == [5, 8]"},{"name":"Preserves their original order","code":"assert positive_values[0] == 5 and positive_values[1] == 8"}]},{"title":"33 · Sort order records by amount","unit":"Analyst practice","prompt":"Write sort_orders(orders). Return a new list sorted by amount from highest to lowest. Do not modify the original list.","setup":"","starter":"def sort_orders(orders):\n    # Return a sorted copy, highest amount first\n    pass","hint":"Use sorted(orders, key=..., reverse=True). The key should read the amount field.","solution":"def sort_orders(orders):\n    return sorted(orders, key=lambda order: order[\"amount\"], reverse=True)","tests":[{"name":"Sorts highest amount first","code":"orders=[{\"id\":1,\"amount\":1200},{\"id\":2,\"amount\":5400},{\"id\":3,\"amount\":800}]\nresult=sort_orders(orders)\nassert [row[\"id\"] for row in result] == [2,1,3]"},{"name":"Leaves original list unchanged","code":"orders=[{\"id\":1,\"amount\":1200},{\"id\":2,\"amount\":5400}]\nsort_orders(orders)\nassert [row[\"id\"] for row in orders] == [1,2]"}]},{"title":"34 · OOP foundations: classes, objects and behaviour","unit":"Intermediate Python","prompt":"Create Customer(name, city) with a label() method returning 'Name — City'.","setup":"","starter":"class Customer:\n    pass","hint":"Initialise instance attributes in __init__. Return the formatted label from the method.","solution":"class Customer:\n    def __init__(self, name, city):\n        self.name = name\n        self.city = city\n    def label(self):\n        return f'{self.name} — {self.city}'","tests":[{"name":"Initialises an instance","code":"c=Customer('Asha','Chennai')\nassert (c.name,c.city)==('Asha','Chennai')"},{"name":"Returns a readable label","code":"assert Customer('Asha','Chennai').label()=='Asha — Chennai'"}]},{"title":"35 · Constructors, __init__ and the meaning of self","unit":"Intermediate Python","prompt":"Create InventoryItem(name, quantity, unit_cost) with a total_value() method.","setup":"","starter":"class InventoryItem:\n    def __init__(self, name, quantity, unit_cost):\n        pass\n    def total_value(self):\n        pass","hint":"Store the three values on self. total_value() returns quantity multiplied by unit_cost.","solution":"class InventoryItem:\n    def __init__(self, name, quantity, unit_cost):\n        self.name = name\n        self.quantity = quantity\n        self.unit_cost = unit_cost\n    def total_value(self):\n        return self.quantity * self.unit_cost","tests":[{"name":"Stores instance state","code":"item=InventoryItem('Pen',4,12.5)\nassert (item.name,item.quantity,item.unit_cost)==('Pen',4,12.5)"},{"name":"Calculates inventory value","code":"assert InventoryItem('Book',3,80).total_value()==240"}]},{"title":"36 · Instance attributes versus class attributes","unit":"Intermediate Python","prompt":"Create TeamMember with class attribute organisation='DataTrail', instance attribute name and describe().","setup":"","starter":"class TeamMember:\n    organisation = 'DataTrail'\n    def __init__(self, name):\n        pass\n    def describe(self):\n        pass","hint":"Set name on self. Read organisation through self.organisation.","solution":"class TeamMember:\n    organisation = 'DataTrail'\n    def __init__(self, name):\n        self.name = name\n    def describe(self):\n        return f'{self.name} @ {self.organisation}'","tests":[{"name":"Keeps instance names separate","code":"a=TeamMember('Asha'); b=TeamMember('Rahul')\nassert (a.name,b.name)==('Asha','Rahul')"},{"name":"Uses the shared class attribute","code":"assert a.describe()=='Asha @ DataTrail'"}]},{"title":"37 · classmethod, staticmethod and alternative constructors","unit":"Intermediate Python","prompt":"Implement Product.from_record(row) and Product.valid_sku(sku), which accepts non-empty alphanumeric strings.","setup":"","starter":"class Product:\n    def __init__(self, sku, price):\n        self.sku, self.price = sku, price\n    @classmethod\n    def from_record(cls, row):\n        pass\n    @staticmethod\n    def valid_sku(sku):\n        pass","hint":"Use @classmethod and cls(...) for construction. Use @staticmethod for independent validation.","solution":"class Product:\n    def __init__(self, sku, price):\n        self.sku, self.price = sku, price\n    @classmethod\n    def from_record(cls, row):\n        return cls(row['sku'], row['price'])\n    @staticmethod\n    def valid_sku(sku):\n        return isinstance(sku, str) and sku.isalnum()","tests":[{"name":"Constructs an object from a record","code":"p=Product.from_record({'sku':'PEN42','price':10})\nassert (p.sku,p.price)==('PEN42',10)"},{"name":"Validates a SKU","code":"assert Product.valid_sku('PEN42') is True and Product.valid_sku('pen-42') is False"}]},{"title":"38 · Encapsulation, properties and controlled state","unit":"Intermediate Python","prompt":"Implement BankAccount with a read-only balance property and deposit(amount). Reject non-positive deposits with ValueError.","setup":"","starter":"class BankAccount:\n    def __init__(self, opening=0): self._balance = opening\n    @property\n    def balance(self): pass\n    def deposit(self, amount): pass","hint":"Store the value in _balance. Validate before changing it; do not add a public balance setter.","solution":"class BankAccount:\n    def __init__(self, opening=0): self._balance = opening\n    @property\n    def balance(self): return self._balance\n    def deposit(self, amount):\n        if amount <= 0: raise ValueError('deposit must be positive')\n        self._balance += amount","tests":[{"name":"Exposes a read-only balance","code":"a=BankAccount(100)\nassert a.balance==100"},{"name":"Deposits update the balance","code":"a=BankAccount(100); a.deposit(50)\nassert a.balance==150"},{"name":"Rejects invalid deposits","code":"a=BankAccount(100)\ntry: a.deposit(-5)\nexcept ValueError: rejected=True\nelse: rejected=False\nassert rejected and a.balance==100"}]},{"title":"39 · Inheritance, super() and method resolution","unit":"Intermediate Python","prompt":"Create Employee and Manager. Manager must reuse Employee initialisation and add team_size.","setup":"","starter":"class Employee:\n    def __init__(self, name): self.name = name\nclass Manager(Employee):\n    def __init__(self, name, team_size): pass","hint":"Use class Manager(Employee), call super().__init__(name), then set team_size.","solution":"class Employee:\n    def __init__(self, name): self.name = name\nclass Manager(Employee):\n    def __init__(self, name, team_size):\n        super().__init__(name)\n        self.team_size = team_size","tests":[{"name":"Inherits employee state","code":"m=Manager('Asha',5)\nassert m.name=='Asha'"},{"name":"Adds manager-specific state","code":"assert m.team_size==5 and isinstance(m,Employee)"}]},{"title":"40 · Method overriding and runtime polymorphism","unit":"Intermediate Python","prompt":"Create NoDiscount and TenPercentOff classes with the same final_price(price) method.","setup":"","starter":"class NoDiscount:\n    def final_price(self, price): pass\nclass TenPercentOff:\n    def final_price(self, price): pass","hint":"Override final_price in each class. A caller should not need to know which policy it received.","solution":"class NoDiscount:\n    def final_price(self, price): return price\nclass TenPercentOff:\n    def final_price(self, price): return price * 0.9","tests":[{"name":"NoDiscount preserves price","code":"assert NoDiscount().final_price(100)==100"},{"name":"TenPercentOff applies a discount","code":"assert TenPercentOff().final_price(100)==90"}]},{"title":"41 · Duck typing and structural interfaces","unit":"Intermediate Python","prompt":"Implement total_price(items). Each item has a numeric price attribute; do not require one specific class.","setup":"","starter":"def total_price(items):\n    pass","hint":"Sum item.price for each supplied object.","solution":"def total_price(items):\n    return sum(item.price for item in items)","tests":[{"name":"Accepts a custom product class","code":"class Pen:\n def __init__(self,p): self.price=p\nassert total_price([Pen(10),Pen(20)])==30"},{"name":"Accepts unrelated object types","code":"class Book:\n def __init__(self,p): self.price=p\nassert total_price([Pen(5),Book(15)])==20"}]},{"title":"42 · Composition versus inheritance","unit":"Intermediate Python","prompt":"Create Order(customer, items). Expose customer_name and total(). Each item has name and price.","setup":"","starter":"class Order:\n    def __init__(self, customer, items): pass\n    @property\n    def customer_name(self): pass\n    def total(self): pass","hint":"Store the customer and item objects, then delegate to their attributes.","solution":"class Order:\n    def __init__(self, customer, items):\n        self.customer, self.items = customer, list(items)\n    @property\n    def customer_name(self): return self.customer.name\n    def total(self): return sum(item.price for item in self.items)","tests":[{"name":"Reads customer through composition","code":"class Customer:\n def __init__(self,name): self.name=name\nclass Item:\n def __init__(self,name,price): self.name=name; self.price=price\no=Order(Customer('Asha'),[Item('Pen',10),Item('Book',50)])\nassert o.customer_name=='Asha'"},{"name":"Aggregates component values","code":"assert o.total()==60"}]},{"title":"43 · Dunder methods: repr, equality and length","unit":"Intermediate Python","prompt":"Implement Product with __repr__, __eq__ based on sku, and __len__ returning the sku length.","setup":"","starter":"class Product:\n def __init__(self, sku): self.sku=sku\n def __repr__(self): pass\n def __eq__(self, other): pass\n def __len__(self): pass","hint":"Use isinstance() inside equality so unrelated types compare safely.","solution":"class Product:\n def __init__(self, sku): self.sku=sku\n def __repr__(self): return f'Product({self.sku!r})'\n def __eq__(self, other): return isinstance(other,Product) and self.sku==other.sku\n def __len__(self): return len(self.sku)","tests":[{"name":"Returns useful representation","code":"assert repr(Product('PEN'))==\"Product('PEN')\""},{"name":"Compares by SKU value","code":"assert Product('PEN')==Product('PEN') and Product('PEN')!=Product('BOOK')"},{"name":"Supports len()","code":"assert len(Product('PEN'))==3"}]},{"title":"44 · dataclasses for structured records","unit":"Intermediate Python","prompt":"Create a dataclass SalesLine with sku, quantity and unit_price. Add a total property.","setup":"","starter":"from dataclasses import dataclass\n@dataclass\nclass SalesLine:\n sku:str\n quantity:int\n unit_price:float\n @property\n def total(self): pass","hint":"Use @dataclass and return quantity multiplied by unit_price from a property.","solution":"from dataclasses import dataclass\n@dataclass\nclass SalesLine:\n sku:str\n quantity:int\n unit_price:float\n @property\n def total(self): return self.quantity*self.unit_price","tests":[{"name":"Creates an initialised record","code":"line=SalesLine('PEN',3,10)\nassert (line.sku,line.quantity,line.unit_price)==('PEN',3,10)"},{"name":"Calculates line total","code":"assert line.total==30"}]},{"title":"45 · Abstract base classes and enforced interfaces","unit":"Intermediate Python","prompt":"Implement DiscountPolicy as an ABC and FixedDiscount as a concrete class whose apply(price) subtracts a fixed amount.","setup":"","starter":"from abc import ABC, abstractmethod\nclass DiscountPolicy(ABC):\n @abstractmethod\n def apply(self, price): pass\nclass FixedDiscount(DiscountPolicy): pass","hint":"Use ABC and abstractmethod. The concrete subclass must implement apply().","solution":"from abc import ABC, abstractmethod\nclass DiscountPolicy(ABC):\n @abstractmethod\n def apply(self, price): raise NotImplementedError\nclass FixedDiscount(DiscountPolicy):\n def __init__(self, amount): self.amount=amount\n def apply(self, price): return max(0,price-self.amount)","tests":[{"name":"Implements the abstract interface","code":"policy=FixedDiscount(15)\nassert isinstance(policy,DiscountPolicy)"},{"name":"Applies discount without negative result","code":"assert policy.apply(100)==85 and policy.apply(10)==0"}]},{"title":"46 · Protocols and structural typing","unit":"Intermediate Python","prompt":"Implement read_revenue(source). The source has fetch_rows() returning dictionaries with amount values.","setup":"","starter":"def read_revenue(source):\n    pass","hint":"Call source.fetch_rows() and sum the amount field. Do not check its concrete class.","solution":"def read_revenue(source):\n    return sum(row['amount'] for row in source.fetch_rows())","tests":[{"name":"Works with a matching source","code":"class Source:\n def fetch_rows(self): return [{'amount':10},{'amount':15}]\nassert read_revenue(Source())==25"},{"name":"Accepts a different implementation","code":"class OtherSource:\n def fetch_rows(self): return []\nassert read_revenue(OtherSource())==0"}]},{"title":"47 · Iterable, iterator and next()","unit":"Intermediate Python","prompt":"Implement first_item(iterable). Return the first item or None when empty.","setup":"","starter":"def first_item(iterable):\n    pass","hint":"Call iter(), then next() inside try/except StopIteration.","solution":"def first_item(iterable):\n    iterator=iter(iterable)\n    try: return next(iterator)\n    except StopIteration: return None","tests":[{"name":"Reads the first value","code":"assert first_item([10,20])==10"},{"name":"Handles empty iterable","code":"assert first_item([]) is None"},{"name":"Accepts a generator","code":"assert first_item(x for x in [7,8])==7"}]},{"title":"48 · Custom iterators with __iter__ and __next__","unit":"Intermediate Python","prompt":"Implement Countdown(start) that yields start down to 1 and then stops.","setup":"","starter":"class Countdown:\n def __init__(self,start): self.current=start\n def __iter__(self): pass\n def __next__(self): pass","hint":"Return self from __iter__. Raise StopIteration once current is below 1.","solution":"class Countdown:\n def __init__(self,start): self.current=start\n def __iter__(self): return self\n def __next__(self):\n  if self.current<1: raise StopIteration\n  value=self.current; self.current-=1\n  return value","tests":[{"name":"Yields descending values","code":"assert list(Countdown(4))==[4,3,2,1]"},{"name":"Handles zero","code":"assert list(Countdown(0))==[]"}]},{"title":"49 · Generators and yield","unit":"Intermediate Python","prompt":"Implement paid_amounts(rows) as a generator yielding only Paid order amounts.","setup":"","starter":"def paid_amounts(rows):\n    pass","hint":"Use yield instead of building and returning a list.","solution":"def paid_amounts(rows):\n    for row in rows:\n        if row['status']=='Paid': yield row['amount']","tests":[{"name":"Yields paid values","code":"rows=[{'amount':10,'status':'Paid'},{'amount':5,'status':'Pending'},{'amount':7,'status':'Paid'}]\nassert list(paid_amounts(rows))==[10,7]"},{"name":"Returns a generator object","code":"assert hasattr(paid_amounts([]),'__next__')"}]},{"title":"50 · Generator expressions and lazy pipelines","unit":"Intermediate Python","prompt":"Implement total_large_orders(rows, threshold) using a generator expression and sum().","setup":"","starter":"def total_large_orders(rows, threshold):\n    pass","hint":"Generate qualifying amounts lazily; do not create an intermediate list.","solution":"def total_large_orders(rows, threshold):\n    return sum(row['amount'] for row in rows if row['amount']>=threshold)","tests":[{"name":"Totals values meeting the threshold","code":"rows=[{'amount':5},{'amount':12},{'amount':20}]\nassert total_large_orders(rows,10)==32"},{"name":"Returns zero when none qualify","code":"assert total_large_orders([{'amount':2}],10)==0"}]},{"title":"51 · Closures and enclosing scope","unit":"Intermediate Python","prompt":"Implement make_multiplier(factor). Return a function that multiplies each supplied value by the remembered factor.","setup":"","starter":"def make_multiplier(factor):\n def multiply(value): pass\n return multiply","hint":"Define an inner function that reads factor from the enclosing scope, then return it.","solution":"def make_multiplier(factor):\n def multiply(value): return value*factor\n return multiply","tests":[{"name":"Remembers its factor","code":"double=make_multiplier(2)\nassert double(5)==10"},{"name":"Creates independent closures","code":"triple=make_multiplier(3)\nassert triple(5)==15 and double(5)==10"}]},{"title":"52 · Decorators and functions as first-class objects","unit":"Intermediate Python","prompt":"Implement count_calls(func). The wrapper must return the original result and expose a calls counter.","setup":"","starter":"def count_calls(func):\n def wrapper(*args,**kwargs): pass\n wrapper.calls=0\n return wrapper","hint":"Use a wrapper attribute. Increment once per call and pass arguments through.","solution":"from functools import wraps\ndef count_calls(func):\n @wraps(func)\n def wrapper(*args,**kwargs):\n  wrapper.calls+=1\n  return func(*args,**kwargs)\n wrapper.calls=0\n return wrapper","tests":[{"name":"Preserves the wrapped result","code":"@count_calls\ndef add(a,b): return a+b\nassert add(2,3)==5"},{"name":"Counts repeated calls","code":"add(1,1)\nassert add.calls==2"}]},{"title":"53 · Decorator factories, functools.wraps and metadata","unit":"Intermediate Python","prompt":"Implement repeat(times) as a decorator factory. The decorated function runs times times and returns its final result.","setup":"","starter":"def repeat(times):\n def decorate(func):\n  def wrapper(*args,**kwargs): pass\n  return wrapper\n return decorate","hint":"The outer function captures times; the decorator receives the function; the wrapper repeats the call and uses @wraps.","solution":"from functools import wraps\ndef repeat(times):\n def decorate(func):\n  @wraps(func)\n  def wrapper(*args,**kwargs):\n   result=None\n   for _ in range(times): result=func(*args,**kwargs)\n   return result\n  return wrapper\n return decorate","tests":[{"name":"Repeats the call","code":"calls=[]\n@repeat(3)\ndef work(v): calls.append(v); return v*2\nassert work(4)==8 and calls==[4,4,4]"},{"name":"Preserves function metadata","code":"assert work.__name__=='work'"}]},{"title":"54 · Recursion, base cases and recursive structures","unit":"Intermediate Python","prompt":"Implement flatten(values) to flatten a nested list of values using recursion.","setup":"","starter":"def flatten(values):\n result=[]\n return result","hint":"If an item is a list, recursively extend the output. Otherwise append it.","solution":"def flatten(values):\n result=[]\n for value in values:\n  if isinstance(value,list): result.extend(flatten(value))\n  else: result.append(value)\n return result","tests":[{"name":"Flattens nested lists","code":"assert flatten([1,[2,[3]],4])==[1,2,3,4]"},{"name":"Handles empty nested lists","code":"assert flatten([[],[1]])==[1]"}]},{"title":"55 · Higher-order functions, lambda and sorting keys","unit":"Intermediate Python","prompt":"Implement sort_orders(orders) to return a new list from highest amount to lowest without mutating the input.","setup":"","starter":"def sort_orders(orders):\n pass","hint":"Use sorted() with key reading amount and reverse=True.","solution":"def sort_orders(orders):\n return sorted(orders,key=lambda row:row['amount'],reverse=True)","tests":[{"name":"Sorts descending by amount","code":"rows=[{'id':1,'amount':10},{'id':2,'amount':50}]\nassert [r['id'] for r in sort_orders(rows)]==[2,1]"},{"name":"Leaves original order unchanged","code":"rows=[{'id':1,'amount':10},{'id':2,'amount':50}]\nsort_orders(rows)\nassert [r['id'] for r in rows]==[1,2]"}]},{"title":"56 · itertools, collections and functools","unit":"Intermediate Python","prompt":"Implement status_counts(statuses) using Counter and return a normal dictionary.","setup":"","starter":"def status_counts(statuses):\n pass","hint":"Create Counter from the iterable and convert it to dict.","solution":"from collections import Counter\ndef status_counts(statuses):\n return dict(Counter(statuses))","tests":[{"name":"Counts repeated statuses","code":"assert status_counts(['Paid','Pending','Paid'])=={'Paid':2,'Pending':1}"},{"name":"Handles empty input","code":"assert status_counts([])=={}"}]},{"title":"57 · Custom exceptions and domain-specific error handling","unit":"Intermediate Python","prompt":"Implement InvalidDiscountError and validate_discount(rate). Accept only rates from zero through one inclusive.","setup":"","starter":"class InvalidDiscountError(ValueError): pass\ndef validate_discount(rate): pass","hint":"Create a subclass of ValueError and raise it when the rate is outside the allowed range.","solution":"class InvalidDiscountError(ValueError): pass\ndef validate_discount(rate):\n if not 0<=rate<=1: raise InvalidDiscountError('rate must be between 0 and 1')\n return rate","tests":[{"name":"Accepts a valid rate","code":"assert validate_discount(.25)==.25"},{"name":"Rejects a rate above one","code":"try: validate_discount(1.2)\nexcept InvalidDiscountError: rejected=True\nelse: rejected=False\nassert rejected"}]},{"title":"58 · Context manager protocol and deterministic cleanup","unit":"Intermediate Python","prompt":"Implement ManagedFlag. active is True inside the with block and False after exit.","setup":"","starter":"class ManagedFlag:\n def __enter__(self): pass\n def __exit__(self, exc_type, exc, tb): pass","hint":"Set active in __enter__, return self, and reset it in __exit__. Do not suppress exceptions.","solution":"class ManagedFlag:\n def __enter__(self): self.active=True; return self\n def __exit__(self, exc_type, exc, tb):\n  self.active=False\n  return False","tests":[{"name":"Activates on entry","code":"r=ManagedFlag()\nwith r as active: assert active.active is True"},{"name":"Cleans up after exit","code":"assert r.active is False"}]},{"title":"59 · Type hints, Optional, collections.abc and TypedDict","unit":"Intermediate Python","prompt":"Implement build_customer_label(record) with an annotated dictionary input and string output.","setup":"","starter":"def build_customer_label(record: dict[str,str]) -> str:\n pass","hint":"Read name and city from the dictionary and return 'Name — City'.","solution":"def build_customer_label(record: dict[str,str]) -> str:\n return f\"{record['name']} — {record['city']}\"","tests":[{"name":"Formats the supplied fields","code":"assert build_customer_label({'name':'Asha','city':'Chennai'})=='Asha — Chennai'"},{"name":"Has a return annotation","code":"assert build_customer_label.__annotations__['return'] is str"}]},{"title":"60 · Unit testing, pytest fixtures and mocking","unit":"Intermediate Python","prompt":"Implement revenue_for_customer(repository, customer_id). Ask the repository for that customer's orders and sum their amounts.","setup":"","starter":"def revenue_for_customer(repository, customer_id):\n pass","hint":"Use dependency injection: call repository.orders_for(customer_id), then sum amount.","solution":"def revenue_for_customer(repository, customer_id):\n return sum(order['amount'] for order in repository.orders_for(customer_id))","tests":[{"name":"Uses the injected repository","code":"class FakeRepo:\n def orders_for(self,c): return [{'amount':10},{'amount':15}] if c==7 else []\nassert revenue_for_customer(FakeRepo(),7)==25"},{"name":"Returns zero for no orders","code":"assert revenue_for_customer(FakeRepo(),99)==0"}]},{"title":"61 · Packages, virtual environments, logging and CLI design","unit":"Intermediate Python","prompt":"Implement parse_report_args(args) with argparse. Require --input and accept optional integer --limit defaulting to 100.","setup":"","starter":"def parse_report_args(args):\n import argparse\n parser=argparse.ArgumentParser()\n pass","hint":"Create the parser, add both arguments and call parse_args(args).","solution":"def parse_report_args(args):\n import argparse\n parser=argparse.ArgumentParser()\n parser.add_argument('--input',required=True)\n parser.add_argument('--limit',type=int,default=100)\n return parser.parse_args(args)","tests":[{"name":"Parses explicit options","code":"a=parse_report_args(['--input','sales.csv','--limit','25'])\nassert (a.input,a.limit)==('sales.csv',25)"},{"name":"Uses the default limit","code":"assert parse_report_args(['--input','x.csv']).limit==100"}]},{"title":"62 · INTERMEDIATE CHECKPOINT · Build a reusable order model","unit":"Intermediate Python","prompt":"Implement OrderModel(customer_name, items). It should return total, number_of_items and a summary string.","setup":"","starter":"class OrderModel:\n def __init__(self, customer_name, items): pass\n @property\n def total(self): pass\n @property\n def number_of_items(self): pass\n def summary(self): pass","hint":"Store item objects. Aggregate their total and quantity; do not hard-code a concrete item class.","solution":"class OrderModel:\n def __init__(self, customer_name, items): self.customer_name=customer_name; self.items=list(items)\n @property\n def total(self): return sum(item.total for item in self.items)\n @property\n def number_of_items(self): return sum(item.quantity for item in self.items)\n def summary(self): return f'{self.customer_name}: {self.number_of_items} units, total {self.total:.2f}'","tests":[{"name":"Aggregates item totals","code":"class Line:\n def __init__(self,q,p): self.quantity=q; self.total=q*p\norder=OrderModel('Asha',[Line(2,10),Line(1,50)])\nassert order.total==70"},{"name":"Counts units and formats a summary","code":"assert order.number_of_items==3 and order.summary()=='Asha: 3 units, total 70.00'"}]},{"title":"63 · Descriptors and managed attribute access","unit":"Advanced Python","prompt":"Implement PositiveNumber and use it for Product.price. Reject zero and negative prices.","setup":"","starter":"class PositiveNumber:\n def __set_name__(self,owner,name): pass\n def __get__(self,instance,owner): pass\n def __set__(self,instance,value): pass\nclass Product:\n price=PositiveNumber()\n def __init__(self,price): self.price=price","hint":"Store the value in instance.__dict__ under the name received by __set_name__.","solution":"class PositiveNumber:\n def __set_name__(self,owner,name): self.name=name\n def __get__(self,instance,owner):\n  if instance is None: return self\n  return instance.__dict__[self.name]\n def __set__(self,instance,value):\n  if value<=0: raise ValueError('price must be positive')\n  instance.__dict__[self.name]=value\nclass Product:\n price=PositiveNumber()\n def __init__(self,price): self.price=price","tests":[{"name":"Stores a valid descriptor value","code":"p=Product(10)\nassert p.price==10"},{"name":"Rejects a non-positive value","code":"p=Product(10)\ntry: p.price=0\nexcept ValueError: rejected=True\nelse: rejected=False\nassert rejected and p.price==10"}]},{"title":"64 · Metaclasses and class creation hooks","unit":"Advanced Python","prompt":"Implement PluginMeta to register every subclass of Plugin by class name, but not Plugin itself.","setup":"","starter":"class PluginMeta(type):\n registry={}\n def __new__(mcls,name,bases,namespace): pass\nclass Plugin(metaclass=PluginMeta): pass","hint":"Subclass type, call super().__new__, then register classes with a base class.","solution":"class PluginMeta(type):\n registry={}\n def __new__(mcls,name,bases,namespace):\n  cls=super().__new__(mcls,name,bases,namespace)\n  if bases: mcls.registry[name]=cls\n  return cls\nclass Plugin(metaclass=PluginMeta): pass","tests":[{"name":"Does not register the root class","code":"assert 'Plugin' not in PluginMeta.registry"},{"name":"Registers concrete subclasses","code":"class CSVPlugin(Plugin): pass\nassert PluginMeta.registry['CSVPlugin'] is CSVPlugin"}]},{"title":"65 · Multiple inheritance, MRO and cooperative super()","unit":"Advanced Python","prompt":"Implement linearised_names(cls) to return the class names in its MRO as a list.","setup":"","starter":"def linearised_names(cls):\n pass","hint":"Use cls.__mro__ and extract each base's __name__.","solution":"def linearised_names(cls):\n return [base.__name__ for base in cls.__mro__]","tests":[{"name":"Returns the complete resolution order","code":"class A: pass\nclass B(A): pass\nassert linearised_names(B)==['B','A','object']"},{"name":"Includes object at the end","code":"assert linearised_names(dict)[-1]=='object'"}]},{"title":"66 · Object identity, references and mutability","unit":"Advanced Python","prompt":"Implement same_object(left, right) using identity and same_value(left, right) using equality.","setup":"","starter":"def same_object(left,right): pass\ndef same_value(left,right): pass","hint":"Use is for object identity and == for value equality.","solution":"def same_object(left,right): return left is right\ndef same_value(left,right): return left == right","tests":[{"name":"Distinguishes identity and equality","code":"a=[1,2]; b=[1,2]; c=a\nassert same_value(a,b) is True and same_object(a,b) is False and same_object(a,c) is True"},{"name":"Compares values","code":"assert same_value(10,10) is True"}]},{"title":"67 · Shallow copy versus deep copy","unit":"Advanced Python","prompt":"Implement clone_report(report) using deepcopy so nested lists in the clone do not affect the original.","setup":"","starter":"def clone_report(report): pass","hint":"Import copy and return copy.deepcopy(report).","solution":"import copy\ndef clone_report(report): return copy.deepcopy(report)","tests":[{"name":"Creates a new outer object","code":"original={'sales':[10,20]}; cloned=clone_report(original)\nassert cloned is not original"},{"name":"Copies nested mutable objects","code":"original={'sales':[10,20]}; cloned=clone_report(original); cloned['sales'].append(30)\nassert original['sales']==[10,20]"}]},{"title":"68 · Garbage collection, reference cycles and weak references","unit":"Advanced Python","prompt":"Implement weak_lookup(reference). Return the referenced object if alive, otherwise None.","setup":"","starter":"def weak_lookup(reference): pass","hint":"Calling a weak reference returns the target or None after collection.","solution":"def weak_lookup(reference): return reference()","tests":[{"name":"Returns a live target","code":"import weakref\nclass Box: pass\nobj=Box(); ref=weakref.ref(obj)\nassert weak_lookup(ref) is obj"},{"name":"Returns None after target is gone","code":"import weakref\nclass Box: pass\nobj=Box(); ref=weakref.ref(obj); del obj\nassert weak_lookup(ref) is None"}]},{"title":"69 · Big-O analysis and algorithmic trade-offs","unit":"Advanced Python","prompt":"Implement has_duplicates(values) using a set so you do not compare every pair.","setup":"","starter":"def has_duplicates(values): pass","hint":"Track values already seen and return immediately when a repeat appears.","solution":"def has_duplicates(values):\n seen=set()\n for value in values:\n  if value in seen: return True\n  seen.add(value)\n return False","tests":[{"name":"Finds repeated values","code":"assert has_duplicates([1,2,3,2]) is True"},{"name":"Accepts unique values","code":"assert has_duplicates([1,2,3]) is False"},{"name":"Handles empty input","code":"assert has_duplicates([]) is False"}]},{"title":"70 · Choosing advanced structures: deque, heapq and bisect","unit":"Advanced Python","prompt":"Implement top_k(values, k) using heapq.nlargest.","setup":"","starter":"def top_k(values,k): pass","hint":"Import nlargest from heapq and delegate the selection.","solution":"from heapq import nlargest\ndef top_k(values,k): return nlargest(k,values)","tests":[{"name":"Returns largest k values","code":"assert top_k([4,1,9,2,7],3)==[9,7,4]"},{"name":"Handles k larger than input","code":"assert top_k([2,1],5)==[2,1]"}]},{"title":"71 · Profiling with timeit and cProfile","unit":"Advanced Python","prompt":"Implement frequency_table(values) with collections.Counter. In practice, profile alternatives with representative data.","setup":"","starter":"def frequency_table(values): pass","hint":"Use Counter and return a plain dictionary.","solution":"from collections import Counter\ndef frequency_table(values): return dict(Counter(values))","tests":[{"name":"Counts frequent values","code":"assert frequency_table(['A','B','A'])=={'A':2,'B':1}"},{"name":"Handles empty input","code":"assert frequency_table([])=={}"}]},{"title":"72 · Memoisation and functools.lru_cache","unit":"Advanced Python","prompt":"Implement fibonacci(n) with lru_cache and recursion.","setup":"","starter":"def fibonacci(n): pass","hint":"Decorate with @lru_cache(maxsize=None) and use the two recursive base cases.","solution":"from functools import lru_cache\n@lru_cache(maxsize=None)\ndef fibonacci(n):\n if n<2: return n\n return fibonacci(n-1)+fibonacci(n-2)","tests":[{"name":"Calculates known Fibonacci values","code":"assert [fibonacci(n) for n in range(8)]==[0,1,1,2,3,5,8,13]"},{"name":"Uses cache on repeated calls","code":"fibonacci.cache_clear(); fibonacci(10)\nassert fibonacci.cache_info().hits>0"}]},{"title":"73 · Async functions, coroutines and await","unit":"Advanced Python","prompt":"Implement async_total(values) as an async function returning the sum. This browser exercise validates its coroutine signature.","setup":"","starter":"async def async_total(values): pass","hint":"Use async def and return sum(values).","solution":"async def async_total(values): return sum(values)","tests":[{"name":"Defines a coroutine function","code":"import inspect\nassert inspect.iscoroutinefunction(async_total)"},{"name":"Keeps the expected function name","code":"assert async_total.__name__=='async_total'"}]},{"title":"74 · asyncio tasks, gather and concurrent I/O orchestration","unit":"Advanced Python","prompt":"Implement make_task_plan(names), returning a stable list of {name, status:'scheduled'} dictionaries.","setup":"","starter":"def make_task_plan(names): pass","hint":"This exercise models task orchestration without calling external services.","solution":"def make_task_plan(names):\n return [{'name':name,'status':'scheduled'} for name in names]","tests":[{"name":"Builds task records","code":"assert make_task_plan(['users','orders'])==[{'name':'users','status':'scheduled'},{'name':'orders','status':'scheduled'}]"},{"name":"Handles an empty plan","code":"assert make_task_plan([])==[]"}]},{"title":"75 · Async cancellation, timeouts and semaphores","unit":"Advanced Python","prompt":"Implement within_limit(active_workers, limit). Return True when capacity remains; reject non-positive limits.","setup":"","starter":"def within_limit(active_workers,limit): pass","hint":"Return active_workers < limit after validating limit > 0.","solution":"def within_limit(active_workers,limit):\n if limit<=0: raise ValueError('limit must be positive')\n return active_workers<limit","tests":[{"name":"Allows work below capacity","code":"assert within_limit(2,5) is True"},{"name":"Blocks work at capacity","code":"assert within_limit(5,5) is False"},{"name":"Rejects invalid capacity","code":"try: within_limit(0,0)\nexcept ValueError: rejected=True\nelse: rejected=False\nassert rejected"}]},{"title":"76 · Threading, multiprocessing and concurrency choices","unit":"Advanced Python","prompt":"Implement choose_executor(workload). Return process for cpu and thread for io; reject unknown values.","setup":"","starter":"def choose_executor(workload): pass","hint":"Choose the approach based on whether the bottleneck is CPU or I/O.","solution":"def choose_executor(workload):\n if workload=='cpu': return 'process'\n if workload=='io': return 'thread'\n raise ValueError('workload must be cpu or io')","tests":[{"name":"Selects processes for CPU workload","code":"assert choose_executor('cpu')=='process'"},{"name":"Selects threads for I/O workload","code":"assert choose_executor('io')=='thread'"},{"name":"Rejects unknown workload","code":"try: choose_executor('memory')\nexcept ValueError: rejected=True\nelse: rejected=False\nassert rejected"}]},{"title":"77 · The GIL and free-threaded CPython builds","unit":"Advanced Python","prompt":"Implement apply_adjustments(balance, adjustments) as a deterministic sequential calculation.","setup":"","starter":"def apply_adjustments(balance,adjustments): pass","hint":"Apply each adjustment in order and return the final balance.","solution":"def apply_adjustments(balance,adjustments):\n for adjustment in adjustments: balance += adjustment\n return balance","tests":[{"name":"Applies all adjustments","code":"assert apply_adjustments(100,[10,-5,2])==107"},{"name":"Handles no adjustments","code":"assert apply_adjustments(25,[])==25"}]},{"title":"78 · Locks, queues and shared-state safety","unit":"Advanced Python","prompt":"Implement drain_queue(values) using queue.Queue and return values in FIFO order.","setup":"","starter":"def drain_queue(values):\n from queue import Queue\n pass","hint":"Put each value into the queue, then get them back until the queue is empty.","solution":"def drain_queue(values):\n from queue import Queue\n work=Queue()\n for value in values: work.put(value)\n result=[]\n while not work.empty(): result.append(work.get())\n return result","tests":[{"name":"Preserves FIFO order","code":"assert drain_queue(['a','b','c'])==['a','b','c']"},{"name":"Handles an empty queue","code":"assert drain_queue([])==[]"}]},{"title":"79 · Streaming data pipelines with generators","unit":"Advanced Python","prompt":"Implement paid_city_amounts(rows) as a generator yielding (clean_city, amount) for each Paid row.","setup":"","starter":"def paid_city_amounts(rows): pass","hint":"Yield one tuple per qualifying row. Do not build a result list.","solution":"def paid_city_amounts(rows):\n for row in rows:\n  if row.get('status')=='Paid': yield (row['city'].strip().title(),float(row['amount']))","tests":[{"name":"Yields cleaned city and amount","code":"rows=[{'city':' chennai ','amount':'10','status':'Paid'},{'city':'Pune','amount':'5','status':'Pending'}]\nassert list(paid_city_amounts(rows))==[('Chennai',10.0)]"},{"name":"Returns a generator","code":"assert hasattr(paid_city_amounts([]),'__next__')"}]},{"title":"80 · Reliable ETL: validation, idempotency and data quality","unit":"Advanced Python","prompt":"Implement deduplicate_orders(rows). Keep the first record for each order_id and preserve input order.","setup":"","starter":"def deduplicate_orders(rows):\n result=[]\n pass","hint":"Track seen IDs in a set. Append only the first occurrence.","solution":"def deduplicate_orders(rows):\n result=[]\n seen=set()\n for row in rows:\n  order_id=row['order_id']\n  if order_id not in seen:\n   seen.add(order_id); result.append(row)\n return result","tests":[{"name":"Keeps first version of each order","code":"rows=[{'order_id':1,'v':'first'},{'order_id':1,'v':'second'},{'order_id':2,'v':'only'}]\nassert deduplicate_orders(rows)==[rows[0],rows[2]]"},{"name":"Preserves first-seen order","code":"rows=[{'order_id':'B'},{'order_id':'A'},{'order_id':'B'}]\nassert [r['order_id'] for r in deduplicate_orders(rows)]==['B','A']"}]},{"title":"81 · Python security: eval, pickle and untrusted input","unit":"Advanced Python","prompt":"Implement safe_json_object(text). Parse JSON and return a dictionary only; reject other JSON values with ValueError.","setup":"","starter":"def safe_json_object(text): pass","hint":"Use json.loads(), check isinstance(value, dict), and reject arrays, strings and numbers.","solution":"import json\ndef safe_json_object(text):\n value=json.loads(text)\n if not isinstance(value,dict): raise ValueError('expected a JSON object')\n return value","tests":[{"name":"Accepts JSON objects","code":"assert safe_json_object('{\"amount\":12}')=={'amount':12}"},{"name":"Rejects JSON arrays","code":"try: safe_json_object('[1,2]')\nexcept ValueError: rejected=True\nelse: rejected=False\nassert rejected"}]},{"title":"82 · Generics, TypeVar and reusable typed containers","unit":"Advanced Python","prompt":"Implement generic Box[T] that stores a value and returns it from get().","setup":"","starter":"from typing import Generic, TypeVar\nT=TypeVar('T')\nclass Box(Generic[T]):\n def __init__(self,value:T): pass\n def get(self)->T: pass","hint":"Create T=TypeVar('T'), inherit Generic[T], and annotate value and get().","solution":"from typing import Generic, TypeVar\nT=TypeVar('T')\nclass Box(Generic[T]):\n def __init__(self,value:T): self.value=value\n def get(self)->T: return self.value","tests":[{"name":"Returns stored integer","code":"assert Box[int](42).get()==42"},{"name":"Preserves stored string","code":"assert Box[str]('report').get()=='report'"}]},{"title":"83 · Dependency injection and application architecture","unit":"Advanced Python","prompt":"Implement RevenueService(repository). Its total() calls repository.fetch() and sums amount.","setup":"","starter":"class RevenueService:\n def __init__(self,repository): pass\n def total(self): pass","hint":"Store the injected repository on self. Do not create a concrete repository inside the service.","solution":"class RevenueService:\n def __init__(self,repository): self.repository=repository\n def total(self): return sum(row['amount'] for row in self.repository.fetch())","tests":[{"name":"Uses injected repository","code":"class FakeRepository:\n def fetch(self): return [{'amount':10},{'amount':15}]\nassert RevenueService(FakeRepository()).total()==25"},{"name":"Handles no rows","code":"class EmptyRepository:\n def fetch(self): return []\nassert RevenueService(EmptyRepository()).total()==0"}]},{"title":"84 · ADVANCED CHECKPOINT · Production-grade analytics pipeline","unit":"Advanced Python","prompt":"Implement build_sales_report(rows). Deduplicate by order_id (first wins), count unique orders, total Paid amounts and group paid revenue by cleaned city.","setup":"","starter":"def build_sales_report(rows):\n pass","hint":"Create a seen set and a unique list inside this function to keep the first row for each order_id. Then aggregate Paid rows by cleaned city.","solution":"def build_sales_report(rows):\n    seen = set()\n    unique = []\n    for row in rows:\n        order_id = row['order_id']\n        if order_id not in seen:\n            seen.add(order_id)\n            unique.append(row)\n\n    paid_revenue = 0.0\n    revenue_by_city = {}\n    for row in unique:\n        if row.get('status') == 'Paid':\n            amount = float(row['amount'])\n            city = row['city'].strip().title()\n            paid_revenue += amount\n            revenue_by_city[city] = revenue_by_city.get(city, 0) + amount\n\n    return {\n        'orders': len(unique),\n        'paid_revenue': paid_revenue,\n        'revenue_by_city': revenue_by_city\n    }","tests":[{"name":"Counts unique records","code":"rows=[{'order_id':1,'city':'Chennai','amount':10,'status':'Paid'},{'order_id':1,'city':'Chennai','amount':10,'status':'Paid'},{'order_id':2,'city':'Pune','amount':5,'status':'Pending'}]\nassert build_sales_report(rows)['orders']==2"},{"name":"Totals paid revenue only once","code":"rows=[{'order_id':1,'city':'chennai','amount':10,'status':'Paid'},{'order_id':1,'city':'chennai','amount':10,'status':'Paid'},{'order_id':2,'city':'Pune','amount':5,'status':'Pending'}]\nassert build_sales_report(rows)['paid_revenue']==10"},{"name":"Cleans city grouping","code":"rows=[{'order_id':1,'city':' chennai ','amount':10,'status':'Paid'}]\nassert build_sales_report(rows)['revenue_by_city']=={'Chennai':10}"}]}];
